public class Solution {
    // CONTRACT: number of runs of equal adjacent characters.
    // "aabbbca" -> 4. Precondition: s.length() >= 1.
    public static int runs(String s) {
        int count = 0;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) != s.charAt(i - 1)) {
                count++;
            }
        }
        return count;
    }
}

